  testWidgets(
      'showSongInfo == true with no track shows the idle "nothingness" label',
      (tester) async {
    final provider = FakeAudioPlayerProvider();
    const config = DotScreenConfig(showSongInfo: true);

    await tester.pumpWidget(
      wrapWithProvider(
        provider,
        const SizedBox(
          width: 400,
          height: 400,
          child: DotHero(config: config),
        ),
      ),
    );

    expect(find.text('nothingness'), findsOneWidget);
  });

  // ---------------------------------------------------------------------------
  // B-020 / B-035: song-info overlay must never intersect the centered dot.
  // ---------------------------------------------------------------------------

  testWidgets(
      'song-info overlay (long artist/title) stays above the centered dot at normal text size',
      (tester) async {
    final provider = FakeAudioPlayerProvider(
      spectrumData: List<double>.filled(8, 1.0),
      songInfo: SongInfo(
        track: AudioTrack(
          path: '/sdcard/Music/01-undercover-49.opus',
          title: 'A Very Long Song Title That Should Ellipsize Correctly And Never Clip',
          artist:
              'A Very Long Artist Name That Should Ellipsize Correctly Too',
        ),
        isPlaying: true,
        position: 0,
        duration: 200000,
      ),
    );

    const config = DotScreenConfig(showSongInfo: true, textScale: 1.0);

    await tester.pumpWidget(
      wrapWithProvider(
        provider,
        const SizedBox(
          width: 400,
          height: 400,
          child: DotHero(config: config),
        ),
      ),
    );

    final dotRect = tester.getRect(find.byKey(const ValueKey('dot-circle')));
    final titleRect = tester.getRect(find.byKey(const ValueKey('dot-song-info')));

    // Title should end strictly above the dot.
    expect(titleRect.bottom <= dotRect.top, isTrue);
    // And the overlay should remain within the hero band.
    expect(titleRect.bottom <= 400.0 + 0.5, isTrue);
  });

  testWidgets(
      'song-info overlay (long artist/title) stays above the centered dot at maximum text size',
      (tester) async {
    final provider = FakeAudioPlayerProvider(
      spectrumData: List<double>.filled(8, 1.0),
