        const SizedBox(
          width: 400,
          height: 400,
          child: DotHero(config: config),
        ),
      ),
    );

    final dotRect = tester.getRect(find.byKey(const ValueKey('dot-circle')));
    final titleRect = tester.getRect(find.byKey(const ValueKey('dot-song-info')));

    expect(titleRect.bottom <= dotRect.top, isTrue);
    expect(titleRect.bottom <= 400.0 + 0.5, isTrue);
  });
